import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import nock from 'nock';
import { post } from '../src/post';

/** nock hands the request body to the reply callback as a urlencoded string. */
function parseForm(body: unknown): Record<string, string> {
  if (typeof body === 'string') return Object.fromEntries(new URLSearchParams(body));
  if (body && typeof body === 'object') return body as Record<string, string>;
  return {};
}

describe('post() — token revocation cleanup', () => {
  let envBackup: NodeJS.ProcessEnv;
  let logSpy: ReturnType<typeof vi.spyOn>;
  let logs: string[];

  beforeEach(() => {
    envBackup = { ...process.env };
    for (const k of Object.keys(process.env)) {
      if (k.startsWith('STATE_')) delete process.env[k];
    }
    logs = [];
    logSpy = vi.spyOn(console, 'log').mockImplementation((msg: string) => {
      logs.push(String(msg));
    });
    nock.disableNetConnect();
  });

  afterEach(() => {
    logSpy.mockRestore();
    nock.cleanAll();
    nock.enableNetConnect();
    for (const k of Object.keys(process.env)) {
      if (!(k in envBackup)) delete process.env[k];
    }
    Object.assign(process.env, envBackup);
  });

  it('revokes the token and logs success', async () => {
    process.env.STATE_access_token = '[REDACTED]';
    process.env.STATE_logfire_url = 'https://logfire.test';

    let revokeBody: Record<string, string> = {};
    const scope = nock('https://logfire.test')
      .post('/api/oauth/revoke')
      .matchHeader('user-agent', /^logfire-auth-action\/\d+\.\d+\.\d+$/)
      .reply(200, (_uri, body) => {
        revokeBody = parseForm(body);
        return '';
      });

    await post();

    expect(scope.isDone()).toBe(true);
    expect(revokeBody.token).toBe('WORKLOAD-TOKEN');
    expect(revokeBody.token_type_hint).toBe('access_token');
    expect(logs).toContain('::debug::Revoked workload token');
  });

  it('skips revocation when skip_cleanup is set (no network call)', async () => {
    process.env.STATE_access_token = '[REDACTED]';
    process.env.STATE_logfire_url = 'https://logfire.test';
    process.env.STATE_skip_cleanup = 'true';

    // No interceptor registered — if post() made a request, nock would throw.
    await post();

    expect(logs.some((l) => l.includes('skip-cleanup is set'))).toBe(true);
  });

  it('no-ops when there is no token', async () => {
    await post();
    expect(logs).toContain('::debug::No token to revoke');
  });

  it('warns when the Logfire URL was not saved', async () => {
    process.env.STATE_access_token = '[REDACTED]';
    await post();
    expect(logs.some((l) => l.includes('::warning::Cannot revoke token'))).toBe(true);
  });

  it('warns (without failing) when revocation returns a non-2xx', async () => {
    process.env.STATE_access_token = '[REDACTED]';
    process.env.STATE_logfire_url = 'https://logfire.test';

    // 400 is not retryable, so this is a single call.
    nock('https://logfire.test').post('/api/oauth/revoke').reply(400, 'bad request');

    await post();

    expect(logs.some((l) => l.includes('::warning::Token revocation returned non-200'))).toBe(true);
  });

  it('warns (without failing) when revocation throws after retries', async () => {
    process.env.STATE_access_token = '[REDACTED]';
    process.env.STATE_logfire_url = 'https://logfire.test';

    // Network error is retryable: initial attempt + 3 retries = 4 errors.
    nock('https://logfire.test')
      .post('/api/oauth/revoke')
      .times(4)
      .replyWithError('socket hang up');

    await post();

    expect(logs.some((l) => l.includes('::warning::Token revocation failed'))).toBe(true);
  }, 10000);
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import * as http from 'node:http';
import * as https from 'node:https';
import * as net from 'node:net';
import * as fs from 'node:fs';
import * as os from 'node:os';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';
import {
  getProxyForUrl,
  inNoProxy,
  requestWithRetry,
  resolveProxyPort,
  selectServername,
} from '../src/http-client';

/**
 * Generate a throwaway self-signed cert (CN=localhost) into a fresh temp dir.
 * Done at test time rather than committing key material to the repo.
 */
function makeSelfSignedCert(): { dir: string; key: Buffer; cert: Buffer } {
  const dir = fs.mkdtempSync(join(os.tmpdir(), 'logfire-tls-'));
  const keyPath = join(dir, 'key.pem');
  const certPath = join(dir, 'cert.pem');
  execFileSync(
    'openssl',
    [
      'req',
      '-x509',
      '-newkey',
      'rsa:2048',
      '-nodes',
      '-keyout',
      keyPath,
      '-out',
      certPath,
      '-days',
      '1',
      '-subj',
      '/CN=localhost',
      '-addext',
      'subjectAltName=DNS:localhost,IP:127.0.0.1',
    ],
    { stdio: 'ignore' },
  );
  return { dir, key: fs.readFileSync(keyPath), cert: fs.readFileSync(certPath) };
}

/** Start a server and resolve once it is listening, returning its port. */
function listen(server: http.Server | https.Server): Promise<number> {
  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      const addr = server.address() as net.AddressInfo;
      resolve(addr.port);
    });
  });
}

describe('getProxyForUrl', () => {
  it('returns empty when no proxy env is set', () => {
    expect(getProxyForUrl('https://x.com', {})).toBe('');
  });

  it('uses HTTPS_PROXY for https targets', () => {
    expect(getProxyForUrl('https://x.com', { HTTPS_PROXY: 'http://p:8080' })).toBe('http://p:8080');
  });

  it('uses HTTP_PROXY for http targets', () => {
    expect(getProxyForUrl('http://x.com', { HTTP_PROXY: 'http://p:8080' })).toBe('http://p:8080');
  });

  it('does not fall back from https to HTTP_PROXY', () => {
    expect(getProxyForUrl('https://x.com', { HTTP_PROXY: 'http://p:8080' })).toBe('');
  });

  it('falls back to ALL_PROXY', () => {
    expect(getProxyForUrl('https://x.com', { ALL_PROXY: 'http://all:1' })).toBe('http://all:1');
  });

  it('honors NO_PROXY=*', () => {
    expect(getProxyForUrl('https://x.com', { HTTPS_PROXY: 'http://p', NO_PROXY: '*' })).toBe('');
  });

  it('honors NO_PROXY suffix match', () => {
    expect(
      getProxyForUrl('https://api.x.com', { HTTPS_PROXY: 'http://p', NO_PROXY: 'x.com' }),
    ).toBe('');
  });

  it('proxies when NO_PROXY does not match', () => {
    expect(
      getProxyForUrl('https://x.com', { HTTPS_PROXY: 'http://p', NO_PROXY: 'other.com' }),
    ).toBe('http://p');
  });

  it('ignores NO_PROXY entry with a mismatched port', () => {
    expect(
      getProxyForUrl('https://x.com:8443', { HTTPS_PROXY: 'http://p', NO_PROXY: 'x.com:443' }),
    ).toBe('http://p');
  });

  it('returns empty for an unparseable target URL', () => {
    expect(getProxyForUrl('http://[not a url', { HTTPS_PROXY: 'http://p' })).toBe('');
  });

  it('ignores a NO_PROXY entry that normalizes to empty', () => {
    // "." normalizes to an empty host and must not match anything.
    expect(getProxyForUrl('https://x.com', { HTTPS_PROXY: 'http://p', NO_PROXY: '.' })).toBe(
      'http://p',
    );
  });
});

describe('resolveProxyPort', () => {
