/**
 * Authenticate to Logfire — post entry point (`runs.post`).
 *
 * Thin shim around ./post so the cleanup logic can be unit-tested in isolation.
 */

import { post } from './post';

void post();

/**
 * Authenticate to Logfire — main entry point (`runs.main`).
 *
 * Thin shim: runs the action logic and converts a thrown error into a failed
 * step. The logic lives in ./run so it can be unit-tested in isolation.
 */

import { run } from './run';
import { setFailed } from './actions';

void run().catch((error: unknown) => {
  setFailed(error instanceof Error ? error.message : String(error));
});

/**
 * Authenticate to Logfire — post-action cleanup logic.
 *
 * Revokes the workload token issued during the main step via the RFC 7009
 * revocation endpoint (`POST /api/oauth/revoke`). Runs as the `post` entry
 * point, so it executes even when the job fails. Best-effort: revocation
 * failures warn rather than fail the job (the token expires on its own).
 */

import { requestWithRetry } from './http-client';
import { getState, warning, debug } from './actions';
import { USER_AGENT } from './version';

export async function revokeToken(revokeUrl: string, token: string): Promise<boolean> {
  const formBody = new URLSearchParams({
    token,
    token_type_hint: 'access_token',
  }).toString();

  const response = await requestWithRetry(
    revokeUrl,
    {
      method: 'POST',
      headers: {
        'User-Agent': USER_AGENT,
        'Content-Type': 'application/x-www-form-urlencoded',
        'Content-Length': Buffer.byteLength(formBody),
      },
    },
    formBody,
    {
      onRetry: (r) =>
        debug(`Revoke retry ${r.attempt}/${r.maxRetries} in ${r.delayMs}ms (${r.reason})`),
    },
  );

  return (
    typeof response.statusCode === 'number' &&
    response.statusCode >= 200 &&
    response.statusCode < 300
  );
}

export async function post(): Promise<void> {
  const accessToken = getState('access_token');
  const logfireUrl = getState('logfire_url');

  if (getState('skip_cleanup') === 'true') {
    debug('skip-cleanup is set; leaving the token to expire naturally');
    return;
  }
  if (!accessToken) {
    debug('No token to revoke');
    return;
  }
  if (!logfireUrl) {
    warning('Cannot revoke token: Logfire URL not saved from main step');
    return;
  }

  try {
    const ok = await revokeToken(`${logfireUrl}/api/oauth/revoke`, accessToken);
    if (ok) {
      debug('Revoked workload token');
    } else {
      warning('Token revocation returned non-200 (token will expire naturally)');
    }
  } catch (error) {
    warning(`Token revocation failed: ${(error as Error).message} (token will expire naturally)`);
  }
}

/**
 * Shared HTTP client for the Logfire OIDC action.
 *
 * Wraps Node's built-in http/https with three things the bare modules lack:
 *   - a per-request socket timeout, so a hung connection fails fast instead of
 *     blocking until the job-level timeout;
 *   - HTTP(S) proxy support — plain proxying for http targets and CONNECT
 *     tunneling for https targets — honoring the conventional HTTPS_PROXY /
 *     HTTP_PROXY / ALL_PROXY / NO_PROXY environment variables that Node's
 *     http/https otherwise ignore;
 *   - retry with jittered exponential backoff on transient failures (network
 *     errors, request timeouts, HTTP 408/429, and 5xx). 4xx responses are
 *     returned as-is so the caller can surface a permanent policy rejection.
 *
 * Built-in Node.js modules only — no runtime npm dependencies.
 */

import * as http from 'node:http';
import * as https from 'node:https';
import * as net from 'node:net';
import * as tls from 'node:tls';

const DEFAULT_TIMEOUT_MS = 10000;
const DEFAULT_MAX_RETRIES = 3;
const DEFAULT_BASE_DELAY_MS = 200;
const MAX_DELAY_MS = 10000;

export interface HttpResponse {
  statusCode: number | undefined;
  body: string;
  headers: http.IncomingHttpHeaders;
}

export interface RetryInfo {
  attempt: number;
  maxRetries: number;
  reason: string;
  delayMs: number;
}

export interface RequestOpts {
  /** Max retry attempts on transient failures. Default 3; 0 disables. */
  maxRetries?: number;
  /** Per-request socket timeout in milliseconds. Default 10000. */
  timeoutMs?: number;
  /** Base backoff delay in milliseconds. Default 200. */
  baseDelayMs?: number;
  /** Explicit proxy override; '' / undefined falls back to the proxy env vars. */
  proxy?: string;
  /** Invoked before each retry sleep. */
  onRetry?: (info: RetryInfo) => void;
}

// --- Proxy resolution (HTTPS_PROXY / HTTP_PROXY / ALL_PROXY / NO_PROXY) ---

/** @param noProxy comma/space-separated NO_PROXY list */
export function inNoProxy(hostname: string, port: string, noProxy: string): boolean {
  return noProxy
    .split(/[\s,]+/)
    .filter(Boolean)
    .some((entry) => {
      let host = entry;
      let entryPort = '';
      const m = entry.match(/^(.+):(\d+)$/);
      if (m) {
        host = m[1]!;
        entryPort = m[2]!;
      }
      if (entryPort && entryPort !== String(port)) return false;
      // Normalize leading "*." or "." so ".example.com" matches "example.com".
      host = host.replace(/^\*?\.?/, '');
      if (!host) return false;
      return hostname === host || hostname.endsWith(`.${host}`);
    });
}

/** The port to connect to on a proxy, applying protocol defaults. */
export function resolveProxyPort(proxy: URL): number {
  if (proxy.port) return Number(proxy.port);
  return proxy.protocol === 'https:' ? 443 : 80;
}

/**
 * The SNI servername to present: an explicit override wins; otherwise the
 * hostname, unless it is an IP literal (RFC 6066 forbids SNI for IPs).
 */
export function selectServername(optionServername: unknown, hostname: string): string | undefined {
  if (typeof optionServername === 'string') return optionServername;
  return net.isIP(hostname) ? undefined : hostname;
}

/**
 * Resolve the proxy URL for a target, or '' if it should be reached directly.
 * Mirrors the de-facto `proxy-from-env` semantics.
 */
export function getProxyForUrl(targetUrl: string, env: NodeJS.ProcessEnv = process.env): string {
  let target: URL;
  try {
    target = new URL(targetUrl);
  } catch {
    return '';
  }
  const isHttps = target.protocol === 'https:';
  const port = target.port || (isHttps ? '443' : '80');
  const noProxy = (env.NO_PROXY || env.no_proxy || '').trim();
  if (noProxy === '*') return '';
  if (noProxy && inNoProxy(target.hostname, port, noProxy)) return '';
  const proxy = isHttps
    ? env.HTTPS_PROXY || env.https_proxy || env.ALL_PROXY || env.all_proxy
    : env.HTTP_PROXY || env.http_proxy || env.ALL_PROXY || env.all_proxy;
  return (proxy || '').trim();
}

// --- Single request (timeout + optional proxy) ---

/** @param proxyUrl '' for a direct connection */
export function makeRequest(
  targetUrl: string,
  options: https.RequestOptions,
  body: string | undefined,
  proxyUrl: string,
  timeoutMs: number,
): Promise<HttpResponse> {
  return new Promise<HttpResponse>((resolve, reject) => {
    const target = new URL(targetUrl);
    const isHttps = target.protocol === 'https:';
    // resolve/reject are idempotent once the promise settles, so the first of
    // response-end / error / timeout wins — no explicit "settled" guard needed.
    const succeed = resolve;
    const fail = reject;

    const onResponse = (res: http.IncomingMessage) => {
      let data = '';
      res.setEncoding('utf8');
      res.on('data', (chunk: string) => {
        data += chunk;
      });
      res.on('end', () =>
        succeed({ statusCode: res.statusCode, body: data, headers: res.headers }),
      );
      res.on('error', fail);
    };

    const wire = (req: http.ClientRequest) => {
      req.on('error', fail);
      req.setTimeout(timeoutMs, () => {
        req.destroy(new Error(`Request to ${target.host} timed out after ${timeoutMs}ms`));
      });
      if (body) req.write(body);
      req.end();
    };

    // Direct connection.
    if (!proxyUrl) {
      const transport = isHttps ? https : http;
      wire(transport.request(targetUrl, options, onResponse));
      return;
    }

    const proxy = new URL(proxyUrl);
    const proxyHeaders: Record<string, string> = {};
    if (proxy.username) {
      const creds = `${decodeURIComponent(proxy.username)}:${decodeURIComponent(proxy.password)}`;
      proxyHeaders['Proxy-Authorization'] = `Basic ${Buffer.from(creds).toString('base64')}`;
    }
    const proxyPort = resolveProxyPort(proxy);

    // Plain HTTP through a proxy: send the absolute URL as the request path.
    if (!isHttps) {
      const req = http.request(
        {
          host: proxy.hostname,
          port: proxyPort,
          method: options.method || 'GET',
          path: targetUrl,
          headers: { ...(options.headers || {}), ...proxyHeaders, Host: target.host },
        },
        onResponse,
      );
      wire(req);
      return;
    }

    // HTTPS through a proxy: open a CONNECT tunnel, then run TLS over it.
    const targetPort = target.port || '443';
    const connectReq = http.request({
      host: proxy.hostname,
      port: proxyPort,
      method: 'CONNECT',
      path: `${target.hostname}:${targetPort}`,
      headers: { ...proxyHeaders, Host: `${target.hostname}:${targetPort}` },
    });
    connectReq.on('error', fail);
    connectReq.setTimeout(timeoutMs, () => {
      connectReq.destroy(
        new Error(`Proxy CONNECT to ${target.host} timed out after ${timeoutMs}ms`),
      );
    });
    connectReq.on('connect', (res: http.IncomingMessage, socket: net.Socket) => {
      if (res.statusCode !== 200) {
        socket.destroy();
        fail(new Error(`Proxy CONNECT to ${target.host} failed (HTTP ${res.statusCode})`));
        return;
      }
      // Run TLS over the established tunnel. A request-level `createConnection`
      // is ignored once an Agent is involved, so route it through a one-off
      // Agent whose createConnection returns the tunneled TLS socket (the
      // https-proxy-agent pattern). Forward the caller's TLS trust settings so
      // the tunneled connection verifies like a direct https request would.
      const servername = selectServername(options.servername, target.hostname);
      const tunnelAgent = new https.Agent();
      tunnelAgent.createConnection = (() => {
        const tlsSocket = tls.connect({
          socket,
          servername,
          ca: options.ca,
          rejectUnauthorized: options.rejectUnauthorized,
        });
        tlsSocket.on('error', fail);
        return tlsSocket;
      }) as typeof tunnelAgent.createConnection;
      const req = https.request(targetUrl, { ...options, agent: tunnelAgent }, onResponse);
      wire(req);
    });
    connectReq.end();
  });
}

// --- Retry with jittered exponential backoff ---

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Full-jitter backoff, capped. */
function backoffDelay(base: number, attempt: number): number {
  const ceiling = Math.min(base * 2 ** attempt, MAX_DELAY_MS);
  return Math.floor(Math.random() * ceiling);
}

function isRetryableStatus(status: number | undefined): boolean {
  return (
    status === 408 ||
    status === 429 ||
    (typeof status === 'number' && status >= 500 && status <= 599)
  );
}

/** Make an HTTP(S) request, retrying transient failures. */
export async function requestWithRetry(
  url: string,
  options: https.RequestOptions,
  body?: string,
  opts: RequestOpts = {},
): Promise<HttpResponse> {
  const maxRetries = Number.isFinite(opts.maxRetries)
    ? Math.max(0, opts.maxRetries!)
    : DEFAULT_MAX_RETRIES;
  const timeoutMs = opts.timeoutMs || DEFAULT_TIMEOUT_MS;
  const baseDelayMs = opts.baseDelayMs || DEFAULT_BASE_DELAY_MS;
  const onRetry = opts.onRetry || (() => {});
  const proxyUrl = opts.proxy || getProxyForUrl(url);

  let attempt = 0;
  for (;;) {
    try {
      const response = await makeRequest(url, options, body, proxyUrl, timeoutMs);
      if (attempt < maxRetries && isRetryableStatus(response.statusCode)) {
        const delayMs = backoffDelay(baseDelayMs, attempt);
        onRetry({
          attempt: attempt + 1,
          maxRetries,
          reason: `HTTP ${response.statusCode}`,
          delayMs,
        });
        await sleep(delayMs);
        attempt += 1;
        continue;
      }
      return response;
    } catch (err) {
      if (attempt >= maxRetries) throw err;
      const delayMs = backoffDelay(baseDelayMs, attempt);
      onRetry({ attempt: attempt + 1, maxRetries, reason: (err as Error).message, delayMs });
      await sleep(delayMs);
      attempt += 1;
    }
  }
}

/**
 * Authenticate to Logfire — main logic.
 *
 * Authenticates GitHub Actions with Logfire via RFC 8693 token exchange:
 * 1. Resolves the Logfire API URL from region/url inputs
 * 2. Computes a deterministic traceparent from the run context
 * 3. Fetches a GitHub OIDC JWT
 * 4. Exchanges it for a short-lived Logfire workload token
 *    (`POST /api/oauth/token`). The trust policy decides which scopes the
 *    issued token carries and therefore which Logfire surfaces it can reach.
 * 5. Saves state for the post-action revocation step
 *
 * `run()` throws on failure; the entry shim turns that into `setFailed`.
 */

import * as crypto from 'node:crypto';
import { requestWithRetry, type RequestOpts } from './http-client';
import { getInput, setOutput, saveState, setSecret, debug, info } from './actions';
import { USER_AGENT } from './version';

// --- RFC 8693 token exchange ---

const TOKEN_EXCHANGE_GRANT = 'urn:ietf:params:oauth:grant-type:token-exchange';
const JWT_TOKEN_TYPE = 'urn:ietf:params:oauth:token-type:jwt';

interface TokenResponse {
  access_token: string;
  expires_in: number;
  scope?: string;
}

interface ExchangeParams {
  subjectToken: string;
  audience: string;
  scope: string;
}

export async function exchangeToken(
  tokenUrl: string,
  { subjectToken, audience, scope }: ExchangeParams,
  httpOpts: RequestOpts,
): Promise<TokenResponse> {
  const params = new URLSearchParams({
    grant_type: TOKEN_EXCHANGE_GRANT,
    subject_token: [REDACTED],
    subject_token_type: JWT_TOKEN_TYPE,
    audience,
  });
  if (scope) {
    params.set('scope', scope);
  }
  const formBody = params.toString();

  const response = await requestWithRetry(
    tokenUrl,
    {
      method: 'POST',
      headers: {
        'User-Agent': USER_AGENT,
        'Content-Type': 'application/x-www-form-urlencoded',
        'Content-Length': Buffer.byteLength(formBody),
      },
    },
    formBody,
    httpOpts,
  );

  if (response.statusCode !== 200) {
    let detail = response.body;
    try {
      const parsed = JSON.parse(response.body) as { error_description?: string; error?: string };
      detail = parsed.error_description || parsed.error || detail;
    } catch {
      /* use raw body */
    }
    throw new Error(`Token exchange failed (HTTP ${response.statusCode}): ${detail}`);
  }

  return JSON.parse(response.body) as TokenResponse;
}

// --- GitHub OIDC token fetching ---

export async function getIDToken(audience: string, httpOpts: RequestOpts): Promise<string> {
  const requestUrl = process.env.ACTIONS_ID_TOKEN_REQUEST_URL;
  const requestToken = [REDACTED];

  if (!requestUrl || !requestToken) {
    throw new Error(
      'GitHub OIDC not available. Ensure the job has "permissions: id-token: write" ' +
        'and the workflow uses a supported event trigger.',
    );
  }

  const url = `${requestUrl}&audience=${encodeURIComponent(audience)}`;
  const response = await requestWithRetry(
    url,
    {
      method: 'GET',
      headers: {
        Authorization: `bearer ${requestToken}`,
        Accept: 'application/json',
      },
    },
    undefined,
    httpOpts,
  );

  if (response.statusCode !== 200) {
    throw new Error(
      `Failed to get GitHub OIDC token (HTTP ${response.statusCode}): ${response.body}`,
    );
  }

  return (JSON.parse(response.body) as { value: string }).value;
}

// --- Traceparent computation ---

function sha256hex(input: string): string {
  return crypto.createHash('sha256').update(input).digest('hex');
}

export function computeTraceId(runId: string, runAttempt: string): string {
  return sha256hex(`logfire:github:trace:${runId}:${runAttempt}`).substring(0, 32);
}

export function computeJobSpanId(runId: string, runAttempt: string, jobName: string): string {
  return sha256hex(`logfire:github:job:${runId}:${runAttempt}:${jobName}`).substring(0, 16);
}

// --- URL resolution ---

const REGION_URLS: Record<string, string> = {
  us: 'https://logfire-us.pydantic.dev',
  eu: 'https://logfire-eu.pydantic.dev',
  'staging-eu': 'https://logfire-eu.pydantic.info',
};

export function resolveUrl(region: string, url: string): string {
  if (url) return url;
  if (region) {
    const resolved = REGION_URLS[region];
    if (!resolved) {
      throw new Error(
        `Unknown region '${region}'. Use: us, eu, staging-eu, or provide a custom url.`,
      );
    }
    return resolved;
  }
  return REGION_URLS.us!;
}

// --- Audience resolution ---

export interface AudienceInputs {
  audienceInput: string;
  organization: string;
  project: string;
  resolvedUrl: string;
}

export interface ResolvedAudience {
  /** `aud` claim requested for the GitHub OIDC JWT. */
  oidcAudience: string;
  /** RFC 8693 `audience` form parameter sent to the exchange. */
  exchangeAudience: string;
}

/**
 * The OIDC JWT `aud` claim and the RFC 8693 exchange audience are always set to
 * the same value — the backend's audience check requires them to match. Two
 * mutually-exclusive modes:
 *   - Explicit `audience`: used verbatim. It must already encode whatever
 *     org/project path the backend expects, so `organization`/`project` are
 *     rejected to avoid an ambiguous double-encoding.
 *   - Otherwise: built from `organization` (+ optional `project`) as a path
 *     under the resolved Logfire URL, which the backend parses to route.
 */
export function resolveAudience({
  audienceInput,
  organization,
  project,
  resolvedUrl,
}: AudienceInputs): ResolvedAudience {
  if (audienceInput && (organization || project)) {
    throw new Error(
      'Input "audience" cannot be combined with "organization" or "project". ' +
        'Provide a full audience that already encodes the org/project path, or ' +
        'omit "audience" and pass "organization" (+ optional "project") instead.',
    );
  }

  if (audienceInput) {
    return { oidcAudience: audienceInput, exchangeAudience: audienceInput };
  }

  if (!organization) {
    throw new Error('Input "organization" is required (unless a full "audience" is provided)');
  }
  const exchangeAudience = project
    ? `${resolvedUrl}/${organization}/${project}`
    : `${resolvedUrl}/${organization}`;
  return { oidcAudience: exchangeAudience, exchangeAudience };
}

// --- Scope parsing ---

/**
 * Scopes are space-separated, per the OAuth / RFC 8693 convention. Collapse any
 * whitespace (newlines, double spaces) the input may carry into single
 * separators. Validity is enforced by the exchange endpoint against the policy.
 */
export function parseScopes(scopesInput: string): string {
  return scopesInput ? scopesInput.split(/\s+/).filter(Boolean).join(' ') : '';
}

// --- HTTP options from inputs ---

export function readHttpOpts(): RequestOpts {
  const maxRetriesInput = parseInt(getInput('max-retries'), 10);
  const timeoutInput = parseInt(getInput('request-timeout'), 10);
  return {
    maxRetries: Number.isNaN(maxRetriesInput) ? undefined : Math.max(0, maxRetriesInput),
    timeoutMs: Number.isNaN(timeoutInput) ? undefined : Math.max(1, timeoutInput) * 1000,
    proxy: getInput('proxy') || undefined,
    onRetry: (r) => debug(`Retry ${r.attempt}/${r.maxRetries} in ${r.delayMs}ms (${r.reason})`),
  };
}

// --- Orchestration ---

export async function run(): Promise<void> {
  // 1. Resolve URL
  const region = getInput('region');
  const url = getInput('url');
  const resolvedUrl = resolveUrl(region, url);

  setOutput('logfire_url', resolvedUrl);
  // Deprecated dash-separated alias; remove in v2.
  setOutput('logfire-url', resolvedUrl);
  debug(`Resolved Logfire URL: ${resolvedUrl}`);

  const httpOpts = readHttpOpts();

  // 2. Compute traceparent. For matrix jobs, GITHUB_JOB collapses across matrix
  //    entries — incorporate `job-id` so each combination gets a unique span id.
  const runId = process.env.GITHUB_RUN_ID || '';
  const runAttempt = process.env.GITHUB_RUN_ATTEMPT || '1';
  const jobId = getInput('job-id') || process.env.GITHUB_JOB || '';

  const traceId = computeTraceId(runId, runAttempt);
  const jobSpanId = computeJobSpanId(runId, runAttempt, jobId);
  const traceparent = `00-${traceId}-${jobSpanId}-01`;

  setOutput('traceparent', traceparent);
  setOutput('trace_id', traceId);
  // Deprecated dash-separated alias; remove in v2.
  setOutput('trace-id', traceId);
  debug(`Traceparent: ${traceparent}`);

  // 3. Resolve the audience.
  const { oidcAudience, exchangeAudience } = resolveAudience({
    audienceInput: getInput('audience'),
    organization: getInput('organization'),
    project: getInput('project'),
    resolvedUrl,
  });

  // 4. Fetch the GitHub OIDC JWT
  const subjectToken = await getIDToken(oidcAudience, httpOpts);
  setSecret(subjectToken);

  const scope = parseScopes(getInput('scopes'));

  // 5. Exchange the OIDC JWT for a Logfire workload token. If the trust policy
  //    rejects the request (claims don't match, requested scope outside the
  //    policy, etc.) the exchange returns an RFC 6749 §5.2 error envelope and
  //    this throws, failing the step.
  const result = await exchangeToken(
    `${resolvedUrl}/api/oauth/token`,
    { subjectToken, audience: exchangeAudience, scope },
    httpOpts,
  );

  const accessToken = [REDACTED];
  const expiresIn = result.expires_in;
  const grantedScopes = result.scope || '';

  setSecret(accessToken);

  setOutput('token', accessToken);
  setOutput('expires_in', String(expiresIn));
  // Deprecated dash-separated alias; remove in v2.
  setOutput('expires-in', String(expiresIn));
  setOutput('scopes', grantedScopes);

  // 6. Save state for the post-action revocation step. `skip-cleanup` is
  //    persisted here (rather than read in the post step) because input env
  //    vars aren't guaranteed in the post context.
  const skipCleanup = getInput('skip-cleanup').toLowerCase() === 'true';
  saveState('access_token', accessToken);
  saveState('logfire_url', resolvedUrl);
  saveState('skip_cleanup', skipCleanup ? 'true' : '');

  info(
    `Logfire OIDC authentication successful (expires in ${expiresIn}s, scopes: ${grantedScopes})`,
  );
}

/**
 * User-Agent identifying this action on every request to Logfire, so
 * server-side telemetry can attribute traffic to the action and its version.
 *
 * Name and version come from package.json — the same source of truth the
 * release script tags from — so the header stays in sync automatically. esbuild
 * inlines these values at bundle time; no package.json ships in `dist/`.
 */

import { name, version } from '../package.json';

// Strip the npm scope: "@pydantic/logfire-auth-action" -> "logfire-auth-action".
const shortName = name.replace(/^@[^/]+\//, '');

export const USER_AGENT = `${shortName}/${version}`;
